    }

    @POST
    @Path("quote")
    @Consumes(MediaType.APPLICATION_JSON)
    @io.swagger.v3.oas.annotations.Operation(summary = "Vendor SDK REST and GraphQL shipping quote")
    @io.swagger.v3.oas.annotations.responses.ApiResponse(responseCode = "200",
            content = @io.swagger.v3.oas.annotations.media.Content(schema = @io.swagger.v3.oas.annotations.media.Schema(implementation = Map.class)))
    public Uni<Response> quote(Workload.Order order, @QueryParam("persist") boolean persist) {
        if (order == null || order.sku() == null || order.sku().isBlank() || order.quantity() < 1)
            return Uni.createFrom().item(error(400, "INVALID_ORDER"));
        return service.quote(order).flatMap(body -> persist ? service.firebase(order.sku())
                                                                     .map(saved -> Response.ok(body).build()) : Uni
                                                                                                                .createFrom()
                                                                                                                .item(Response
                                                                                                                      .ok(body)
                                                                                                                      .build()))
                      .onFailure().invoke(Throwable::printStackTrace).onFailure()
                      .recoverWithItem(f -> error(502, "UPSTREAM_FAILURE"));
    }

    @GET
    @Path("retry/{id}")
    public Uni<Response> retry(@PathParam("id") String id) {
        return service.retry(id).map(v -> Response.ok(Map.of("result", v)).build()).onFailure()
                      .recoverWithItem(f -> error(502, "UPSTREAM_FAILURE"));
    }

    @GET
    @Path("timeout")
    public Uni<Response> timeout() {
        return service.timeout().map(v -> Response.ok(Map.of("result", v)).build()).onFailure()
                      .recoverWithItem(f -> error(504, "UPSTREAM_TIMEOUT"));
    }

    @GET
    @Path("firebase/{id}")
    public Uni<Response> firebase(@PathParam("id") String id) {
        return service.firebase(id).map(body -> Response.ok(body).build()).onFailure().invoke(Throwable::printStackTrace).onFailure()
                      .recoverWithItem(f -> error(502, "FIREBASE_FAILURE"));
    }

    private Response error(int status, String code) {
        return Response.status(status).entity(Map.of("error", Map.of("code", code, "status", status))).build();
    }
}

package bench.guicedee.service;

import com.google.inject.Singleton;
import bench.workload.Workload;
import com.guicedee.vertx.spi.Verticle;
import io.smallrye.mutiny.Uni;
import org.eclipse.microprofile.faulttolerance.*;
import org.eclipse.microprofile.metrics.annotation.Counted;

import java.util.Map;

@Singleton
@Verticle("bench-guicedee-service")
public class Service {
    private final Workload workload = new Workload(com.guicedee.client.Environment.getSystemPropertyOrEnvironment(
            "BENCH_UPSTREAM",
            "http://127.0.0.1:18089"));

    @Counted(name = "benchmark_quotes", absolute = true)
    public Uni<Map<String, Object>> quote(Workload.Order order) {

        return Uni.createFrom().completionStage(() -> workload.quote(order));
    }

    @Retry(maxRetries = 2, delay = 20, jitter = 0)
    public Uni<String> retry(String id) {
        return Uni.createFrom().completionStage(() -> workload.remote("/flaky/" + id));
    }

    @Timeout(50)
    public Uni<String> timeout() {
        return Uni.createFrom().completionStage(() -> workload.remote("/slow"));
    }

    public Uni<Map<String, Object>> firebase(String id) {
        return Uni.createFrom().completionStage(() -> workload.firebase(id));
    }
}

